//! Real-media acceptance for sequential frame streams (WP6a).
//!
//! The fixtures and judging tools are in `common`: three solid colors (red / green / blue, each 1 second, 30 fps, one keyframe per second), freshly generated by ffmpeg. The assertions fall into four categories:
//!
//! 1. **Frame-rate resampling**: when the composition fps changes, the output frame count scales proportionally and matches the output of ffmpeg `-r` frame for frame.
//! 2. **Start point**: whichever segment `from` falls in, the first frame has that segment's color (not the color of the keyframe that the seek landed on).
//! 3. **Tail**: the stream ends (EOF) and does not keep emitting duplicate frames endlessly.
//! 4. **Cross-backend tolerance**: at the same output frame number, the SSIM between the native frame and the ffmpeg frame is ≥ 0.95 (the cross-backend semantic equivalence criterion of `docs/design/bcf/cuccut-format-spec.md` §15.1; the algorithm is the shared implementation in `ccut-render::imgcmp`).
//!
//! If ffmpeg cannot be detected, the whole test is skipped.

mod common;

use media_native::{available, open_frame_stream};
use render_raster::imgcmp;

use common::{
    HEIGHT, SEGMENT, SOURCE_FPS, WIDTH, dominant, ffmpeg_frame_stream, fixture, to_pixmap,
};

/// Drains the whole stream and returns every frame.
fn drain(media: &std::path::Path, from: f64, fps: f64) -> Vec<media_native::RgbaFrame> {
    let mut stream = open_frame_stream(media, from, fps).expect("native sequential frame stream");
    assert_eq!((stream.width(), stream.height()), (WIDTH, HEIGHT));
    let mut frames = Vec::new();
    // Upper-bound guard: the fixture is only 3 seconds long, so no fps should produce this many frames.
    while let Some(frame) = stream.next_frame().expect("decode") {
        frames.push(frame);
        assert!(frames.len() < 10_000, "frame stream did not end (EOF semantics broken)");
    }
    frames
}

/// The composition frame rate determines the output frame count. 3 seconds of material gives 45 / 90 / 180 frames at 15 / 30 / 60 fps, which exactly matches the output frame count of the ffmpeg `-r` pipe.
#[test]
fn the_output_frame_count_follows_the_composition_frame_rate() {
    if !available() {
        return;
    }
    let Some((_dir, media)) = fixture() else {
        return;
    };
    let total = SEGMENT * 3.0;
    for fps in [15.0_f64, 30.0, 60.0] {
        let frames = drain(&media, 0.0, fps);
        assert_eq!(
            frames.len(),
            (total * fps) as usize,
            "at {fps}fps, {total} s of material should yield {} frames",
            (total * fps) as usize
        );
        // The frame count is aligned with ffmpeg `-r` **within the tail tolerance**. At the tail, ffmpeg emits one or two extra frames according to its own CFR padding rules (measured 47 frames at 15 fps and 180 frames at 60 fps), whereas here the stream stops strictly at the right end of the last frame's presentation interval. Downstream, `ccut-render`'s `VideoReader` **freezes the last frame** on EOF, and those one or two extra frames are byte-identical to the frozen picture, so the difference is not observable. Hard-coding the exact numbers would instead turn ffmpeg version differences into fragility in this repo's tests.
        let Some(reference) = ffmpeg_frame_stream(&media, 0.0, fps) else {
            return;
        };
        assert!(
            reference.len().abs_diff(frames.len()) <= 2,
            "at {fps}fps, native {} frames and ffmpeg {} frames differ by more than the end-of-clip tolerance",
            frames.len(),
            reference.len()
        );
    }
}

/// Picture semantics of dup / drop: regardless of the composition frame rate, the time point at which frame k falls determines which segment it is in, and it has that segment's color.
#[test]
fn resampled_frames_keep_their_segment_colour() {
    if !available() {
        return;
    }
    let Some((_dir, media)) = fixture() else {
        return;
    };
    for fps in [15.0_f64, 60.0] {
        let frames = drain(&media, 0.0, fps);
        for (index, expected) in [(0_usize, "red"), (1, "green"), (2, "blue")]
            .map(|(segment, colour)| (((segment as f64 + 0.5) * SEGMENT * fps) as usize, colour))
        {
            assert_eq!(
                dominant(&frames[index]),
                expected,
                "at {fps}fps, frame {index} should fall in the {expected} segment"
            );
        }
    }
}

/// Start semantics: `from` falls in the middle of the green segment, and the first frame is green. It is not the keyframe the seek lands on (GOP = 30 frames; falling back to the keyframe would pick up the red frame before 1.0s).
#[test]
fn the_stream_starts_on_the_frame_that_covers_the_requested_time() {
    if !available() {
        return;
    }
    let Some((_dir, media)) = fixture() else {
        return;
    };
    for (from, expected, remaining_segments) in
        [(0.5, "red", 2.5), (1.5, "green", 1.5), (2.5, "blue", 0.5)]
    {
        let frames = drain(&media, from, SOURCE_FPS);
        assert_eq!(
            dominant(&frames[0]),
            expected,
            "the first frame for from={from} should be {expected}"
        );
        assert_eq!(
            frames.len(),
            (remaining_segments * SOURCE_FPS) as usize,
            "{remaining_segments} s remain after from={from}"
        );
    }
}

/// Segment boundaries do not bleed: the frame just before the first green frame is still red.
#[test]
fn frames_do_not_bleed_across_a_segment_boundary() {
    if !available() {
        return;
    }
    let Some((_dir, media)) = fixture() else {
        return;
    };
    let frames = drain(&media, 0.0, SOURCE_FPS);
    let boundary = (SEGMENT * SOURCE_FPS) as usize;
    assert_eq!(dominant(&frames[boundary - 1]), "red", "last frame of the red segment");
    assert_eq!(dominant(&frames[boundary]), "green", "first frame of the green segment");
}

/// Cross-backend comparison: SSIM between the native frame and the ffmpeg frame at the same output frame number.
///
/// The threshold uses the **0.95** from the text of §15.1. Both sides of this path are at the **source size as is**, unlike the single-frame extraction path, which has to scale each side (`extract_frame.rs` calibrated its threshold to 0.90 because AVFoundation and swscale edge interpolation differ). With no scaler divergence, only the difference in YUV→RGB matrix implementation remains, so the score is much higher.
#[test]
fn native_frames_match_the_ffmpeg_fallback_within_the_cross_backend_tolerance() {
    const SSIM_FLOOR: f64 = 0.95;
    if !available() {
        return;
    }
    let Some((_dir, media)) = fixture() else {
        return;
    };
    let frames = drain(&media, 0.0, SOURCE_FPS);
    let Some(reference) = ffmpeg_frame_stream(&media, 0.0, SOURCE_FPS) else {
        return;
    };
    assert_eq!(frames.len(), reference.len(), "both paths must produce the same number of frames");
    // Take the middle frame of each segment, plus one frame before and after each boundary.
    let probes = [
        15_usize,
        29,
        30,
        45,
        59,
        60,
        75,
        frames.len().saturating_sub(1),
    ];
    for index in probes {
        let measured = imgcmp::compare(&to_pixmap(&frames[index]), &to_pixmap(&reference[index]))
            .expect("sizes match");
        assert!(
            measured.ssim_downsampled >= SSIM_FLOOR,
            "frame {index} cross-backend SSIM (4× downsampled) {:.4} is below {SSIM_FLOOR} \
             (backend {} vs ffmpeg, full-resolution ssim={:.4}, per-channel max deviation {}, flat-region max deviation {})",
            measured.ssim_downsampled,
            media_native::backend(),
            measured.ssim,
            measured.max_deviation,
            measured.flat_max_deviation,
        );
        println!(
            "frame {index} ssim={:.4} ssim_downsampled={:.4} max={} flat={} edge={:.3}%",
            measured.ssim,
            measured.ssim_downsampled,
            measured.max_deviation,
            measured.flat_max_deviation,
            measured.edge_share * 100.0
        );
    }
}

/// A file that cannot be opened is an `Err`, not a panic. The caller relies on this to decide whether to fall back to ffmpeg.
#[test]
fn an_unopenable_source_is_an_error_not_a_panic() {
    if !available() {
        return;
    }
    let dir = tempfile::tempdir().unwrap();
    assert!(open_frame_stream(&dir.path().join("nope.mp4"), 0.0, 30.0).is_err());
    // A file that is not media must likewise be an error, not an empty stream.
    let text = dir.path().join("not-media.mp4");
    std::fs::write(&text, b"definitely not a container").unwrap();
    assert!(open_frame_stream(&text, 0.0, 30.0).is_err());
}
